package com.nextspace.app;

import com.google.gson.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NativeWidgetPolicyTest {
    private final String account="a".repeat(64);
    private JsonObject config(){return JsonParser.parseString("{\"version\":1,\"widgetId\":42,\"accountKey\":\""+account+"\",\"generation\":3,\"title\":\"Work agenda\",\"page\":\"calendar\",\"scopeId\":\"space-work\"}").getAsJsonObject();}
    private JsonObject snapshot(){JsonObject s=config();s.addProperty("state","ready");s.add("rows",JsonParser.parseString("[{\"type\":\"item\",\"recordId\":\"event-one\",\"title\":\"Project review\"}]"));s.add("month",JsonParser.parseString("{\"cells\":[{\"date\":\"2026-11-23\",\"day\":23}]}"));return s;}
    private JsonObject action(String kind){JsonObject a=config();a.addProperty("action",kind);return a;}
    @Test public void currentSnapshotCannotCrossAccountsOrConfigurationGenerations(){assertTrue(NativeWidgetPolicy.snapshotMatches(snapshot(),config(),account));assertFalse(NativeWidgetPolicy.snapshotMatches(snapshot(),config(),"b".repeat(64)));JsonObject newer=config();newer.addProperty("generation",4);assertFalse(NativeWidgetPolicy.snapshotMatches(snapshot(),newer,account));}
    @Test public void deletedOrUnsupportedConfigurationCannotReceivePublication(){assertFalse(NativeWidgetPolicy.snapshotMatches(snapshot(),new JsonObject(),account));JsonObject c=config();c.addProperty("version",2);assertFalse(NativeWidgetPolicy.validConfig(c));assertFalse(NativeWidgetPolicy.snapshotMatches(snapshot(),c,account));}
    @Test public void changedPageAndSpaceCannotPublishOldRows(){JsonObject s=snapshot();s.addProperty("page","board");assertFalse(NativeWidgetPolicy.snapshotMatches(s,config(),account));s=snapshot();s.addProperty("scopeId","all");assertFalse(NativeWidgetPolicy.snapshotMatches(s,config(),account));}
    @Test public void rowActionMustNameAnActualProjectedRecord(){JsonObject a=action("item");a.addProperty("recordId","event-one");assertTrue(NativeWidgetPolicy.actionMatches(a,config(),snapshot(),account));a.addProperty("recordId","outside-scope");assertFalse(NativeWidgetPolicy.actionMatches(a,config(),snapshot(),account));}
    @Test public void monthActionMustNameAnActualCalendarCell(){JsonObject a=action("date");a.addProperty("date","2026-11-23");assertTrue(NativeWidgetPolicy.actionMatches(a,config(),snapshot(),account));a.addProperty("date","2027-01-01");assertFalse(NativeWidgetPolicy.actionMatches(a,config(),snapshot(),account));}
    @Test public void gridDatesUseTheSameCurrentSnapshotFence(){JsonObject s=snapshot();s.remove("month");s.add("calendarGrid",JsonParser.parseString("{\"days\":[{\"date\":\"2026-11-23\"}]}"));JsonObject a=action("date");a.addProperty("date","2026-11-23");assertTrue(NativeWidgetPolicy.actionMatches(a,config(),s,account));a.addProperty("date","2026-11-24");assertFalse(NativeWidgetPolicy.actionMatches(a,config(),s,account));a.addProperty("date","2026-11-23");a.addProperty("generation",2);assertFalse(NativeWidgetPolicy.actionMatches(a,config(),s,account));}
    @Test public void unavailableSnapshotCannotRouteCreateOrOpen(){JsonObject s=snapshot();s.addProperty("state","unavailable");assertFalse(NativeWidgetPolicy.actionMatches(action("create"),config(),s,account));assertFalse(NativeWidgetPolicy.actionMatches(action("open"),config(),s,account));}
    @Test public void staleIntentCannotReuseAReconfiguredWidget(){JsonObject a=action("create");a.addProperty("generation",2);assertFalse(NativeWidgetPolicy.actionMatches(a,config(),snapshot(),account));a=action("create");a.addProperty("accountKey","b".repeat(64));assertFalse(NativeWidgetPolicy.actionMatches(a,config(),snapshot(),account));}
    @Test public void unknownAndMutationActionsAreNeverNativeShortcuts(){for(String name:new String[]{"delete","complete","request","save"})assertFalse(NativeWidgetPolicy.actionMatches(action(name),config(),snapshot(),account));assertTrue(NativeWidgetPolicy.actionMatches(action("create"),config(),snapshot(),account));}
    @Test public void monthFallsBackToAgendaUntilReadableTapTargetsFit(){assertFalse(NativeWidgetPolicy.showMonthGrid(310,450));assertFalse(NativeWidgetPolicy.showMonthGrid(340,449));assertFalse(NativeWidgetPolicy.showMonthGrid(700,210));assertTrue(NativeWidgetPolicy.showMonthGrid(340,450));assertTrue(NativeWidgetPolicy.showMonthGrid(700,600));}
    @Test public void sourceAccessDenialDuringProjectionInvalidatesPublicationProof(){JsonArray clean=new JsonArray(),denied=JsonParser.parseString("[{\"source\":\"calendar\",\"collectionId\":\"calendar-work\"}]").getAsJsonArray();NativeWidgetPolicy.requireUnchangedAccess(clean.toString(),clean);try{NativeWidgetPolicy.requireUnchangedAccess(clean.toString(),denied);fail("An access denial must invalidate an in-flight snapshot");}catch(IllegalStateException expected){}NativeWidgetPolicy.requireUnchangedAccess(denied.toString(),denied);}
    @Test public void persistedDenialHidesSnapshotsAndCatalogEvenBeforeCleanupRuns(){String before="c".repeat(64),after="d".repeat(64);JsonObject snapshotFile=NativeWidgetPolicy.sealProjection(snapshot(),before),catalog=new JsonObject();catalog.addProperty("accountKey",account);catalog.add("sources",JsonParser.parseString("[{\"id\":\"calendar-work\",\"title\":\"Work\"}]"));JsonObject catalogFile=NativeWidgetPolicy.sealProjection(catalog,before);assertEquals(snapshot(),NativeWidgetPolicy.openProjection(snapshotFile,before));assertTrue(NativeWidgetPolicy.openProjection(snapshotFile,after).isEmpty());assertTrue(NativeWidgetPolicy.openProjection(catalogFile,after).isEmpty());}
    @Test public void unknownOrUnstampedStorageNeverGrantsAccess(){String proof="c".repeat(64);assertTrue(NativeWidgetPolicy.openProjection(snapshot(),proof).isEmpty());JsonObject envelope=NativeWidgetPolicy.sealProjection(snapshot(),proof);envelope.addProperty("version",2);assertTrue(NativeWidgetPolicy.openProjection(envelope,proof).isEmpty());assertThrows(IllegalArgumentException.class,()->NativeWidgetPolicy.sealProjection(snapshot(),""));}
}
